func FetchRunningLogs(k8s kube.KubeClient, namespace, pipeline, build, stage string) ([]Log, error) {

	selector := map[string]string{
		"pipeline": pipeline,
		"build":    build,
		"stage":    stage,
	}
	pod, err := k8s.GetPodNameBySelector(namespace, selector)
	if err != nil {
		logrus.Error(err)
		return nil, err
	}

	containers, err := k8s.GetPodContainers(namespace, pod)
	if err != nil {
		logrus.Error(err)
		return nil, err
	}

	logs := make([]Log, 0)
	for _, container := range containers {
		log, err := k8s.GetLog(namespace, pod, container)
		if err != nil {
			logrus.Error(err)
			return nil, err
		}
		encodedContent := base64.StdEncoding.EncodeToString([]byte(log))
		logs = append(logs, Log{Filename: container, Content: encodedContent})
	}

	return logs, nil
}

