func (self *WebServer) dataAuthHandler(c *gin.Context) {
	//authorization 1: t=$timestamp
	token := c.GetString("token")

	t64, err := ginutils.GetQueryInt64(c, "t")
	if err != nil {
		self.resp(c, 401, &CR{
			Message: "No param time",
			Code:    CodeBadData,
		})
		c.Abort()
		return
	}

	//authorization1: verify time
	if time.Now().Unix()-t64 > 60 || time.Now().Unix()-t64 < -60 {
		self.resp(c, 400, &CR{
			Message: "Expire",
			Code:    CodeBadData,
		})
		c.Abort()
		return
	}

	//authorization2: verify hash
	hash, hashExist := c.GetQuery("hash")
	if !hashExist {
		self.resp(c, 400, &CR{
			Message: "No hash",
			Code:    CodeBadData,
		})
		c.Abort()
		return
	}
	querys := c.Request.URL.Query()
	var keys []string
	for k, _ := range querys {
		if k != "hash" {
			keys = append(keys, k)
		}
	}

	h := md5.New()
	sort.Strings(keys)
	for _, key := range keys {
		value := querys.Get(key)
		h.Write([]byte(value))
	}
	h.Write([]byte(token))
	expectHash := hex.EncodeToString(h.Sum(nil))

	if hash != expectHash {
		self.resp(c, 401, &CR{
			Message: "Auth failed",
			Code:    CodeNoAuth,
		})
		c.Abort()
		return
	}
}

